update repair_guides g set steps_ar='["اقرأ Freeze Frame لتحديد الأسطوانة/الأسطوانات المقطوعة.","افحص البواجي واستبدلها إن لزم (مواصفة NGK/Bosch لـ M266).","بدّل كويل الإشعال المشتبه به مع أسطوانة أخرى؛ إن انتقل التقطيع فهو هو.","افحص خراطيم الفاكيوم وفلاب المانيفولد بحثًا عن تسريب أو علوق.","امسح الكود وأعد اختبار القيادة؛ إن عاد، افحص ضغط البنزين."]'::jsonb from fault_codes f where g.fault_code_id=f.id and f.code='P0300';

update fault_codes set name_ar='خليط فقير (بنك 1)', system_ar='الوقود والهواء', symptoms_ar='["تتعل عند التشغيل البارد","قيم Fuel Trim طويلة المدى مرتفعة","تقطيع عرضي بسبب الخليط الفقير"]'::jsonb, causes_ar='["تسريب هواء (بوت السحب، خرطوم PCV)","حساس MAF متسخ (يرافق P0101)","بنزينة ضعيفة أو فلتر مسدود"]'::jsonb where code='P0171';
update repair_guides g set steps_ar='["افحص بصريًا بوت السحب وكل خراطيم الفاكيوم بحثًا عن تشققات (تتقصف بالحرارة في W245 القديمة).","نظف حساس MAF بمنظف مخصص؛ قارن قراءته بالمواصفة.","افحص Fuel Trim طويل المدى في الواقف وعند 2500 لفة/د (فقير في الاثنين = توصيل بنزين؛ فقير في الواقف فقط = هواء).","إن عادت القيم طبيعية بعد اختبار الدخان، أصلح الخرطوم المتسرب وأعد الاختبار."]'::jsonb from fault_codes f where g.fault_code_id=f.id and f.code='P0171';

update fault_codes set name_ar='حساس MAF — نطاق/أداء الدائرة', system_ar='الوقود والهواء', symptoms_ar='["تسارع متقطع","تتعل عند أول ضغطة بنزين","شكاوى من نعومة الفتيس CVT"]'::jsonb, causes_ar='["فيلم MAF الساخن متسخ","بوت السحب بعد MAF ممزق","تآكل في الأسلاك/الكونكتور"]'::jsonb where code='P0101';
