update fault_codes set name_ar='ترموستات ماء التبريد (حرارة أقل من المطلوب)', system_ar='نظام التبريد', symptoms_ar='["الموتور لا يصل 90°C أبدًا","تدفئة الكابينة ضعيفة","استهلاك بنزين أعلى"]'::jsonb, causes_ar='["الترموستات عالق مفتوح (قطعة تآكل كلاسيكية في M266)","ماء تبريد ناقص","انحراف حساس حرارة الماء"]'::jsonb where code='P0128';
update repair_guides g set steps_ar='["تأكد من البيانات الحية: الماء عالق تحت 80°C بعد 15 دقيقة قيادة.","فضّ ماء التبريد واستبدل الترموستات مع الجوان.","املأ ونزّف نظام التبريد حسب إجراء W245.","تأكد من الوصول إلى 87–95°C وثباتها في اختبار قيادة."]'::jsonb from fault_codes f where g.fault_code_id=f.id and f.code='P0128';

