update repair_guides g set steps_ar='["استمع للبنبة وهي تعمل 20–60 ثانية بعد تشغيل بارد.","افحص بلف الكومبينيشن لتآكل الرطوبة (عطل شائع).","اختبر دفع البنبة وخراطيمها بحثًا عن انسداد.","استبدل البنبة أو البلف التالف؛ امسح الكود وأعد اختبار التشغيل البارد."]'::jsonb from fault_codes f where g.fault_code_id=f.id and f.code='P0410';

update fault_codes set name_ar='فلاب المانيفولد عالق مفتوح', system_ar='الوقود والهواء', symptoms_ar='["لمبة الشيك مع واقف خشن","فقدان عزم في الأطوات الأولى","صوت دق من المانيفولد"]'::jsonb, causes_ar='["أكتواتور الفلاب/Swirl عالق (مشكلة معروفة في M266)","كربون على وصلات الفلاب","موتور الأكتواتور تالف"]'::jsonb where code='P2004';
update repair_guides g set steps_ar='["ادخل على وصلة فلاب المانيفولد؛ افحص الحركة الحرة وترسبات الكربون.","نظف الفلاب والوصلات؛ تأكد أن عصا الأكتواتور تتحرك بحرية.","إن كان موتور الأكتواتور ميتًا، استبدل وحدة الفلاب.","امسح الأكواد وتأكد أن الفلاب يتحرك في اختبار بيانات حية."]'::jsonb from fault_codes f where g.fault_code_id=f.id and f.code='P2004';

